test('LHB-51: la puerta de la cuenta guarda en el teléfono solo lo público (nombre público y foto de Clerk), también al editar; y el encabezado se repinta al guardar y al salir',async()=>{
 const CL='https://img.clerk.com/eyJ0eXBlIjoicHJveHkifQ';
 const run=async prof=>{const h=CUENTA_HARNESS({api:async()=>({status:200,body:{profile:prof}})});h.C.user={id:'user_a'};await h.A.require(h.go);await tick();return h.D.store.get()};
 assert.deepEqual(await run({handle:'ana',display_name:'Ana M.',avatar_key:CL,bio:'x',favorite_brand:'y'}),{sub:'user_a',handle:'ana',name:'Ana M.',avatar:CL},'nada de bio ni marca, solo lo del encabezado');
 assert.deepEqual(await run({handle:'ana',display_name:'Ana M.',avatar_key:'https://evil.example/x.png'}),{sub:'user_a',handle:'ana',name:'Ana M.',avatar:''},'una foto que no es de Clerk no se guarda');
 assert.deepEqual(await run({handle:'ana'}),{sub:'user_a',handle:'ana',name:'',avatar:''},'un perfil de antes, sin nombre ni foto, tampoco rompe');
 assert.deepEqual(await run({handle:'ana',display_name:7,avatar_key:7}),{sub:'user_a',handle:'ana',name:'',avatar:''},'ni valores que no son texto');
 /* al editar y guardar, lo guardado trae el nombre y la foto nuevos */
 const o=await EDT({id:'user_a',hasImage:true,imageUrl:AV},{put:b=>({status:200,body:{profile:{handle:b.handle,display_name:'Bea S.',avatar_key:AV55}}})});
 assert.deepEqual(await o.submit(),{ok:true});assert.deepEqual(o.h.D.store.get(),{sub:'user_a',handle:'ana',name:'Bea S.',avatar:AV55},'tras editar, el teléfono guarda el nombre y la foto nuevos');
 /* hoja.js repinta el encabezado cuando se guarda o se borra lo guardado, y app.js se lo da */
 const hj=read('hoja.js').replace(/\r\n/g,'\n'),ap=read('app.js');
 assert.ok(hj.includes("set:v=>{A.LS.set('cuenta2',v);if(A.topAvatar)A.topAvatar();acctTell()}")&&/clear:\(\)=>\{try\{localStorage\.removeItem\('vb_cuenta2'\);localStorage\.removeItem\('vb_cuenta'\)\}catch\(e\)\{\}if\(A\.topAvatar\)A\.topAvatar\(\);acctTell\(\)\}/.test(hj),'guardar y borrar repintan el encabezado (y avisan a los botones de seguir, LHB-60)');
 assert.ok(ap.includes('window.LHB_EXT({topAvatar,'),'app.js le pasa topAvatar a Mi Hoja');
 assert.match(read('sw.js'),/const VERSION='lhb-v166'/,'el shell nuevo se publica con otra versión del caché');
});
test('LHB-51: al salir o al cambiar de cuenta se borra lo guardado de la cuenta anterior, para que el encabezado nunca muestre a una persona con la sesión de otra',async()=>{
 const h=CUENTA_HARNESS({api:async()=>({status:200,body:{profile:{handle:'ana',display_name:'Ana M.',avatar_key:'https://img.clerk.com/eyJ0eXBlIjoicHJveHkifQ'}}})});
 h.C.user={id:'user_a'};await h.A.require(h.go);await tick();assert.equal(h.D.store.get().sub,'user_a','la cuenta A queda guardada');
 h.C.signIn('user_b');assert.equal(h.D.store.get(),null,'de A a B directo: lo de A se borra aunque nadie haya salido');
 h.cache({sub:'user_b',handle:'beto',name:'Beto S.',avatar:''});h.C.signIn(null);assert.equal(h.D.store.get(),null,'al salir se borra');
});
test('LHB-51 (Codex ronda 1): al cargar Clerk, lo guardado de otra cuenta (o de ninguna) se descarta aunque /api/me falle',async()=>{
 for(const [nombre,user] of [['otra cuenta',{id:'user_b'}],['nadie entró',null]]){
  const h=CUENTA_HARNESS({api:async()=>({status:503,body:{}})});h.cache({sub:'user_a',handle:'ana',name:'Ana M.',avatar:''});h.C.user=user;await h.A.require(h.go);await tick();
  assert.equal(h.D.store.get(),null,nombre+': lo de A ya no vale');assert.ok(!h.log.includes('GO'));
 }
 /* la misma cuenta que dice Clerk: se queda (sirve sin conexión) */
 const ok=CUENTA_HARNESS({api:async()=>({status:503,body:{}})});ok.cache({sub:'user_a',handle:'ana',name:'Ana M.',avatar:''});ok.C.user={id:'user_a'};await ok.A.require(ok.go);await tick();assert.equal(ok.D.store.get().sub,'user_a','la misma cuenta se queda');
});
test('LHB-51 (Codex ronda 2): al abrir la app con una cuenta guardada, Clerk confirma quién es; otra cuenta o nadie la borra, sin conexión se queda',async()=>{
 const mk=(user,over)=>{const h=CUENTA_HARNESS(over);h.cache({sub:'user_a',handle:'ana',name:'Ana M.',avatar:''});h.C.user=user;return h};
 let h=mk({id:'user_b'});await h.A.reconcile();assert.equal(h.D.store.get(),null,'Clerk dice B: lo de A se va');
 h=mk(null);await h.A.reconcile();assert.equal(h.D.store.get(),null,'Clerk dice nadie: se va');
 h=mk({id:'user_a'});await h.A.reconcile();assert.equal(h.D.store.get().sub,'user_a','la misma cuenta se queda');
 h=mk({id:'user_b'},{clerk:async()=>{throw new Error('sin red')}});await h.A.reconcile();assert.equal(h.D.store.get().sub,'user_a','sin conexión no se puede saber: se queda');
 let called=0;h=CUENTA_HARNESS({clerk:async()=>{called++;throw new Error('x')}});await h.A.reconcile();assert.equal(called,0,'sin cuenta guardada no se carga Clerk');
 /* y después de confirmar, un cambio de cuenta sigue borrando */
 h=mk({id:'user_a'});await h.A.reconcile();h.cache({sub:'user_a',handle:'ana',name:'Ana M.',avatar:''});h.C.signIn('user_b');assert.equal(h.D.store.get(),null,'el cambio posterior se oye');
 const hj=read('hoja.js');assert.ok(hj.includes("setTimeout(()=>{if(acct.get())CUENTA.reconcile()},2500);"),'hoja.js lo pide al abrir');
});
test('LHB-51 (Codex ronda 3): si al confirmar la cuenta lo guardado era de otra, Mi Hoja ya pintada se vuelve a pasar por la puerta; en otra página no se mueve nada',async()=>{
 const mk=nav=>{const h=CUENTA_HARNESS();h.nav(nav);h.cache({sub:'user_a',handle:'ana',name:'Ana M.',avatar:''});h.C.user={id:'user_b'};return h};
 let h=mk('#/mihoja/perfil');await h.A.reconcile();assert.equal(h.D.store.get(),null);assert.equal(h.log.filter(x=>x==='reroute').length,1,'Perfil de A se repinta por la puerta de B');
 h=mk('#/catalogo');await h.A.reconcile();assert.equal(h.D.store.get(),null);assert.equal(h.log.filter(x=>x==='reroute').length,0,'en otra página no se repinta nada');
 h=mk('#/mihoja/perfil');h.C.user={id:'user_a'};await h.A.reconcile();assert.equal(h.log.filter(x=>x==='reroute').length,0,'la misma cuenta no mueve nada');
});

/* ===================== LHB-38: entradas del pasaporte (diario) con foto, pública, día y marca ===================== */
/* hoja.js corre tal cual (almacenamiento, respaldo, diario y cata guiada) sobre un DOM, un teléfono y una base de fotos de mentira */
function HOJA38(opts){opts=opts||{};
 const vm=require('vm');const src=read('hoja.js').replace(/\r\n/g,'\n');
 const cut=(a,z)=>{const i=src.indexOf(a),j=src.indexOf(z,i);if(i<0||j<0)throw new Error('no está: '+a+' / '+z);return src.slice(i,j)};
 const code=cut('const MES=','try{navigator.storage')+cut('function download(','function backupDue')+cut('const stars=','/* pasaporte */')+cut('/* ---------- cata guiada ---------- */','/* ---------- maridajes');
 const ls=new Map(Object.entries(opts.ls||{}));const localStorage={getItem:k=>ls.has(k)?ls.get(k):null,setItem:(k,v)=>{ls.set(k,String(v))},removeItem:k=>{ls.delete(k)},key:i=>[...ls.keys()][i]??null,get length(){return ls.size}};
 const store=new Map(),idbLog=[];
 const indexedDB={open:(n,v)=>{const r={};idbLog.push(['open',n,v]);setImmediate(()=>{r.result={createObjectStore:s=>idbLog.push(['store',s]),transaction:(sn,mode)=>{const t={};t.objectStore=()=>({put:(val,k)=>{store.set(k,val);idbLog.push(['put',k]);return {}},delete:k=>{store.delete(k);idbLog.push(['del',k]);return {}},get:k=>({result:store.get(k)})});setImmediate(()=>t.oncomplete&&t.oncomplete());return t}};r.onupgradeneeded&&r.onupgradeneeded();r.onsuccess&&r.onsuccess()});return r}};
 const els={};const mkEl=(id)=>({id,value:'',checked:false,textContent:'',dataset:{},clicks:0,click(){this.clicks++}});
 let html='';const view={set innerHTML(h){html=h},get innerHTML(){return html}};
 const present=id=>html.includes('id="'+id+'"');
 const $=s=>{if(s[0]!=='#')return null;const id=s.slice(1);if(!present(id))return null;return els[id]||(els[id]=mkEl(id))};
 const lists={};const $$=s=>lists[s]||[];
 const toasts=[],blobs=[],log=[];const acctBox={v:{sub:'u_a'}};
 const resized=[];
 const ctx={...TT(),window:{addEventListener(t,f){if(opts.win)(opts.win[t]=opts.win[t]||[]).push(f)}},LHB_MERGE:SYNC28().LHB_MERGE,$,$$,view,VBArt:VB111(),esc:s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),toast:m=>toasts.push(m),
  A:{D:()=>opts.D||({artesanos:[{nombre:'Tabaquero B'},{nombre:'Tabaquero A'}]}),cigarById:id=>id==='c1'?{id:'c1',nombre:'Yambú Toro'}:null,artisanName:c=>'Casa Yambú',allCigars:()=>[],
   resizeImage:opts.resize||(async(f,max,q)=>{resized.push([max,q]);return {blob:1}}),hydrate:r=>log.push('hydrate'),route:()=>log.push('route')},
  D:()=>opts.D||({artesanos:[{nombre:'Tabaquero B'},{nombre:'Tabaquero A'}]}),APP_URL:'https://x.test/',acct:{get:()=>acctBox.v},
  bindWheel:()=>{},tagChips:()=>'',subnav:()=>'',backupPanel:()=>'',bindBackup:()=>{},WN:x=>x,cigarOptions:()=>'',
  localStorage,indexedDB,navigator:{},location:{hash:''},scrollY:0,scrollTo:()=>{},confirm:()=>true,setTimeout:()=>0,
  URL:{createObjectURL:b=>{blobs.push(b);return 'blob:x'},revokeObjectURL:()=>{}},document:{createElement:()=>({click(){},remove(){}}),body:{appendChild(){}}},
  FileReader:class{readAsText(f){this.result=f.__text;this.onload()}},Blob,JSON,Date:opts.now?class extends Date{constructor(...a){if(a.length)super(...a);else super(opts.now)}}:Date};
 vm.createContext(ctx);
 vm.runInContext(code+';this.API={okDay,entryDefaults,normalize,upgrade,load,S,save,write,hoy,exportar,importar,saveCata,renderCata,startCata,vDiario,stepBody,NEWDRAFT,FOTOS,PASOS,setCD:v=>{CD=v},getCD:()=>CD,persistDraft,vCata,dropFoto}'+(opts.api?';this.X={'+opts.api+'}':''),ctx);/* LHB-39: opts.D es el catálogo; opts.api, lo de más que la prueba lee */
 return {API:ctx.API,ctx,ls,store,idbLog,els,lists,toasts,blobs,log,resized,acctBox,html:()=>html,set:(k,v)=>{ls.set(k,JSON.stringify(v))}};
}
const E38=(o)=>({id:'d1',fecha:'2026-03-04T02:00:00.000Z',cigarId:null,nombre:'Toro',artesano:'',rating:4,notas:'bien',tags:['madera'],origen:'cata',actualizado:'2026-03-04T02:00:00.000Z',...o});
test('LHB-38: las entradas de antes cargan con sus valores por defecto, sin perder nada; los valores válidos se respetan y los malos se corrigen; correrlo dos veces no cambia nada',()=>{
 const h=HOJA38();const {normalize,okDay}=h.API;const hoy=h.API.hoy();
 const o=normalize({schema:1,diario:[E38({}),E38({id:'d2',consumido:'2026-02-10',publica:true,foto:'dfoto_x',marca:'  Cohiba  ',extra:'queda'}),E38({id:'d3',consumido:'2026-02-30',publica:'si',foto:5,marca:7}),E38({id:'d4',fecha:undefined}),E38({id:'d5',consumido:'2026-13-01'}),E38({id:'d6',consumido:'ayer'}),E38({id:'d7',marca:'x'.repeat(100)}),null,'basura',[1]]});
 const [d1,d2,d3,d4,d5,d6,d7]=o.diario;
 assert.deepEqual([d1.foto,d1.publica,d1.consumido,d1.marca],['',false,'2026-03-04',''],'una entrada de antes: sin foto, privada, el día de su fecha, sin marca');
 assert.equal(d1.nombre,'Toro');assert.equal(d1.rating,4);assert.deepEqual(d1.tags,['madera'],'lo demás queda igual');
 assert.deepEqual([d2.foto,d2.publica,d2.consumido,d2.marca,d2.extra],['dfoto_x',true,'2026-02-10','Cohiba','queda'],'lo válido se respeta (la marca sin espacios de los lados) y un campo extra no se pierde');
 assert.deepEqual([d3.foto,d3.publica,d3.consumido,d3.marca],['',false,'2026-03-04','']," tipos malos y un día que no existe (30 de febrero) se corrigen");
 assert.equal(d4.consumido,hoy,'sin fecha ni día: hoy');
 assert.equal(d5.consumido,'2026-03-04','mes 13 no existe');assert.equal(d6.consumido,'2026-03-04');
 assert.equal(d7.marca.length,60,'la marca se corta a 60');
 assert.deepEqual(o.diario.slice(7),[null,'basura',[1]],'lo que no es una entrada no se toca');
 assert.equal(o.schema,1,'es aditivo: el esquema sigue en 1');
 const twice=JSON.stringify(normalize(JSON.parse(JSON.stringify(o))));assert.equal(twice,JSON.stringify(o),'idempotente');
 for(const v of ['2026-02-28','2024-02-29','2000-01-01'])assert.equal(okDay(v),true,v);for(const v of ['2026-02-29','2026-04-31','2026-00-10','26-01-01','2026-1-1',20260101,null,undefined,'2026-01-01T00:00'])assert.equal(okDay(v),false,String(v));
 /* un perfil nuevo sin diario carga igual */
 assert.deepEqual(normalize({}).diario,[]);
});
test('LHB-38: guardado en el teléfono y respaldo: lo de antes se carga con los valores por defecto, y exportar e importar llevan los cuatro campos nuevos',async()=>{
 /* load() sobre lo guardado de antes */
 const h=HOJA38({ls:{lhb_mihoja_v1:JSON.stringify({schema:1,diario:[E38({})],humidor:[],ratings:{}})}});
 const s=h.API.S();assert.deepEqual([s.diario[0].foto,s.diario[0].publica,s.diario[0].consumido,s.diario[0].marca],['',false,'2026-03-04','']);
 /* exportar: un teléfono con entradas nuevas */
 const mine=[E38({id:'n1',foto:'dfoto_a1',publica:true,consumido:'2026-05-06',marca:'Cohiba'}),E38({id:'n2',fecha:'2026-04-01T10:00:00.000Z',publica:false,consumido:'2026-03-30',marca:''})];
 const a=HOJA38({ls:{lhb_mihoja_v1:JSON.stringify({schema:1,diario:mine,humidor:[],ratings:{}})}});
 a.API.exportar();assert.equal(a.blobs.length,1,'se descargó un archivo');const file=JSON.parse(await a.blobs[0].text());
 assert.equal(file.tipo,'respaldo-mi-hoja');assert.equal(file.schema,1,'el respaldo sigue en el esquema 1');
 const out=file.mihoja.diario;assert.equal(out.length,2);for(const e of out){assert.ok('foto' in e&&'publica' in e&&'consumido' in e&&'marca' in e,e.id+' lleva los cuatro campos')}
 assert.deepEqual(out.map(e=>[e.id,e.foto,e.publica,e.consumido,e.marca]),[['n1','dfoto_a1',true,'2026-05-06','Cohiba'],['n2','',false,'2026-03-30','']]);
 /* importar ese respaldo en un teléfono vacío */
 const b=HOJA38();b.API.importar({__text:JSON.stringify(file)});
 const got=b.API.S().diario.map(e=>[e.id,e.foto,e.publica,e.consumido,e.marca]).sort((x,y)=>x[0].localeCompare(y[0]));
 assert.deepEqual(got,[['n1','dfoto_a1',true,'2026-05-06','Cohiba'],['n2','',false,'2026-03-30','']],'importar conserva foto, pública, día y marca');
 /* importar un respaldo de antes (sin los campos nuevos) los llena */
 const viejo={app:'La Hoja Boricua',tipo:'respaldo-mi-hoja',schema:1,mihoja:{schema:1,diario:[E38({id:'v1'})],humidor:[],ratings:{}}};
 const c=HOJA38();c.API.importar({__text:JSON.stringify(viejo)});const v=c.API.S().diario[0];assert.deepEqual([v.id,v.foto,v.publica,v.consumido,v.marca],['v1','',false,'2026-03-04','']);
 /* importar sobre un teléfono que ya tiene la entrada: gana la más reciente y no pierde los campos */
 const d=HOJA38({ls:{lhb_mihoja_v1:JSON.stringify({schema:1,diario:[E38({id:'n1',actualizado:'2026-01-01T00:00:00.000Z',publica:false})],humidor:[],ratings:{}})}});d.API.importar({__text:JSON.stringify(file)});
 const m=d.API.S().diario.find(e=>e.id==='n1');assert.deepEqual([m.publica,m.foto,m.marca],[true,'dfoto_a1','Cohiba'],'la entrada más nueva del respaldo gana, con sus campos');
});
test('LHB-38: guardar la cata: foto, pública, día y marca van a la entrada; la marca solo si el cigarro es "otro"; un día futuro o inválido se vuelve hoy; por defecto privada y de hoy',()=>{
 const mk=(cd,now)=>{const h=HOJA38({now});const d={...h.API.NEWDRAFT(cd.cigarId||'',cd.nombre||'Toro'),rating:4,...cd};h.API.setCD(d);h.API.saveCata();return {h,e:h.API.S().diario[0]}};
 const hoy='2026-10-27';const now='2026-10-27T15:00:00.000Z';
 let {h,e}=mk({},now);assert.deepEqual([e.foto,e.publica,e.consumido,e.marca],['',false,hoy,''],'por defecto: sin foto, privada, de hoy, sin marca');
 assert.equal(h.API.getCD(),null);assert.equal(h.ctx.location.hash,'#/mihoja/diario');assert.equal(e.origen,'cata');assert.equal(e.rating,4);
 ({e}=mk({foto:'dfoto_z',publica:true,consumido:'2026-10-20',marca:'  Tabaquero A  '},now));assert.deepEqual([e.foto,e.publica,e.consumido,e.marca],['dfoto_z',true,'2026-10-20','Tabaquero A'],'un cigarro "otro": lleva su marca');
 ({e}=mk({cigarId:'c1',nombre:'Yambú Toro',marca:'Cohiba',publica:true},now));assert.equal(e.marca,'','un cigarro del catálogo no lleva marca');assert.equal(e.publica,true);assert.equal(e.artesano,'Casa Yambú');
 for(const bad of ['2026-10-28','2099-01-01','2026-02-30','ayer','',null,undefined,20261020])({e}=mk({consumido:bad},now)),assert.equal(e.consumido,hoy,String(bad)+' se vuelve hoy');
 ({e}=mk({consumido:hoy},now));assert.equal(e.consumido,hoy,'hoy mismo vale');
 ({e}=mk({marca:'x'.repeat(90)},now));assert.equal(e.marca.length,60);
 ({e}=mk({publica:'si'},now));assert.equal(e.publica,true,'cualquier valor verdadero del borrador es pública');({e}=mk({publica:undefined},now));assert.equal(e.publica,false);
 /* sin estrellas no se guarda nada */
 const h2=HOJA38({now});h2.API.setCD({...h2.API.NEWDRAFT('','Toro'),rating:0});h2.API.saveCata();assert.equal(h2.API.S().diario.length,0);
});
test('LHB-38: el formulario de la cata: día (no futuro), marca solo para "otro", foto y pública, todo se guarda en el borrador',async()=>{
 const now='2026-10-27T15:00:00.000Z';const last=h=>h.API.PASOS.length-1;
 const open=(o)=>{const h=HOJA38({now,...o});const d={...h.API.NEWDRAFT(o&&o.cid||'',o&&o.nombre||'Toro'),rating:3,...(o&&o.draft||{})};d.paso=last(h);h.API.setCD(d);h.API.renderCata();return h};
 let h=open();const H=()=>h.html();
 assert.match(H(),/<input id="cFecha" type="date" min="2000-01-01" max="2026-10-27" value="2026-10-27">/,'día: hoy por defecto, sin fechas futuras');
 assert.match(H(),/id="cMarca" maxlength="60"/,'cigarro "otro": pide la marca');assert.match(H(),/<datalist id="cMarcaL"><option value="Tabaquero A"><option value="Tabaquero B"><\/datalist>/,'con las casas del catálogo, en orden');
 assert.ok(/id="cPublica" >/.test(H())||/id="cPublica"\s*>/.test(H()),'pública sin marcar por defecto');assert.ok(!/id="cPublica" checked/.test(H()));assert.match(H(),/solo tú la ves/);
 assert.match(H(),/id="cFotoB">Añadir foto</);assert.ok(!H().includes('cFotoX'),'sin foto no hay "Quitar"');assert.match(H(),/<input type="file" accept="image\/\*" id="cFotoF"/);
 assert.ok(h.log.includes('hydrate'),'las fotos del formulario se pintan');
 /* un cigarro del catálogo no pide marca */
 h=open({cid:'c1',nombre:'Yambú Toro'});assert.ok(!H().includes('cMarca'),'del catálogo: sin marca');assert.match(H(),/id="cSellar"/);
 /* el borrador lleva lo que se escribe */
 h=open();const D=()=>h.API.getCD();const persisted=()=>JSON.parse(h.ls.get('lhb_mihoja_v1')).draft;
 h.els.cFecha.value='2026-10-20';h.els.cFecha.onchange();assert.equal(D().consumido,'2026-10-20');assert.equal(persisted().consumido,'2026-10-20','y se guarda en el teléfono');
 for(const bad of ['2026-10-28','2030-01-01','nada','']){h.els.cFecha.value=bad;h.els.cFecha.onchange();assert.equal(D().consumido,'2026-10-27',JSON.stringify(bad)+' vuelve a hoy');assert.equal(h.els.cFecha.value,'2026-10-27','y el campo lo muestra')}
 h.els.cMarca.value='Cohiba';h.els.cMarca.oninput();assert.equal(D().marca,'Cohiba');assert.equal(persisted().marca,'Cohiba');
 h.els.cPublica.checked=true;h.els.cPublica.onchange();assert.equal(D().publica,true);assert.equal(persisted().publica,true);h.els.cPublica.checked=false;h.els.cPublica.onchange();assert.equal(D().publica,false);
 /* el borrador marcado como pública se ve marcado al abrirlo */
 h=open({draft:{publica:true,marca:'Cohiba',consumido:'2026-10-01'}});assert.match(h.html(),/id="cPublica" checked>/);assert.match(h.html(),/value="Cohiba"/);assert.match(h.html(),/value="2026-10-01"/);
});
test('LHB-38: la foto de la cata: se achica, se guarda en la base de fotos del teléfono con su llave, se puede cambiar y quitar, y los fallos no dejan nada a medias',async()=>{
 const now='2026-10-27T15:00:00.000Z';
 const open=(o)=>{const h=HOJA38({now,...o});h.ctx.location.hash='#/cata';const d={...h.API.NEWDRAFT('','Toro'),rating:3};d.paso=h.API.PASOS.length-1;h.API.setCD(d);h.API.renderCata();return h};
 const pick=(h,f)=>h.els.cFotoF.onchange({target:{files:[f],value:'x'}});const png={type:'image/png',name:'a.png'};
 let h=open();
 h.els.cFotoB.onclick();assert.equal(h.els.cFotoF.clicks,1,'el botón abre el selector');
 await pick(h,png);await tick();
 assert.deepEqual(h.resized,[[1100,.8]],'se achica a 1100 de lado con calidad .8');
 const keys=[...h.store.keys()];assert.equal(keys.length,1);assert.match(keys[0],/^dfoto_[a-z0-9]{6,}$/,'llave propia de las fotos del diario');assert.deepEqual(h.idbLog[0],['open','vitola-boricua',1],'la misma base de fotos que usa app.js');assert.ok(h.idbLog.some(x=>x[0]==='put'&&x[1]===keys[0]));
 assert.equal(h.API.getCD().foto,keys[0]);assert.equal(JSON.parse(h.ls.get('lhb_mihoja_v1')).draft.foto,keys[0],'la llave queda en el borrador');
 assert.match(h.html(),new RegExp('data-photo="'+keys[0]+'"'),'la foto se pinta en el formulario');assert.match(h.html(),/id="cFotoB">Cambiar foto</);assert.match(h.html(),/id="cFotoX">Quitar foto</);
 /* cambiar: la foto nueva reemplaza a la anterior y la anterior se borra del teléfono */
 await pick(h,png);await tick();const k2=[...h.store.keys()];assert.equal(k2.length,1,'queda una sola foto');assert.notEqual(k2[0],keys[0]);assert.equal(h.API.getCD().foto,k2[0]);assert.ok(h.idbLog.some(x=>x[0]==='del'&&x[1]===keys[0]),'la anterior se borró');
 /* quitar */
 h.els.cFotoX.onclick();await tick();assert.equal(h.API.getCD().foto,'');assert.equal(h.store.size,0,'se borra del teléfono');assert.match(h.html(),/id="cFotoB">Añadir foto</);
 /* lo que no es imagen no se achica ni se guarda */
 h.resized.length=0;await pick(h,{type:'text/plain',name:'x.txt'});await tick();assert.deepEqual(h.resized,[]);assert.equal(h.store.size,0);assert.match(h.els.cFotoH.textContent,/Escoge una imagen/);
 /* un fallo al achicar o al guardar deja la foto de antes y lo dice */
 h=open({resize:async()=>{throw new Error('canvas')}});await pick(h,png);await tick();assert.equal(h.API.getCD().foto,'');assert.equal(h.store.size,0);assert.match(h.els.cFotoH.textContent,/No pudimos guardar la foto/);
 /* la base de fotos del teléfono falla */
 const h3=HOJA38({now});h3.ctx.location.hash='#/cata';const d3={...h3.API.NEWDRAFT('','Toro'),rating:3};d3.paso=h3.API.PASOS.length-1;h3.API.setCD(d3);h3.API.renderCata();h3.ctx.indexedDB.open=()=>{const r={};setImmediate(()=>r.onerror&&r.onerror());return r};await pick(h3,png);await tick(20);assert.equal(h3.API.getCD().foto,'');assert.match(h3.els.cFotoH.textContent,/No pudimos guardar la foto/);
 /* una foto que llega cuando el borrador ya es otro (guardó o empezó otra cata) se borra y no toca nada */
 h=open();const g=defer();h.ctx.A.resizeImage=async()=>{await g.p;return {blob:3}};const pend=pick(h,png);await tick();h.API.setCD({...h.API.NEWDRAFT('','Otro'),rating:3});g.ok();await pend;await tick();
 assert.equal(h.store.size,0,'la foto tardía no queda guardada');assert.equal(h.API.getCD().foto,'','y el borrador nuevo no la recibe');
 /* empezar otra cata suelta la foto del borrador que se deja */
 h=open();await pick(h,png);await tick();const viejo=h.API.getCD().foto;assert.ok(viejo);h.API.startCata('','');await tick();assert.equal(h.store.has(viejo),false,'la foto del borrador anterior se borra');
});
test('LHB-38 (Codex ronda 1): sobre la foto manda la última acción; no se pierde la guardada; una foto tardía no cambia la página; empezar otra cata borra la foto abandonada',async()=>{
 const now='2026-10-27T15:00:00.000Z';const png={type:'image/png',name:'a.png'};
 const open=(o)=>{const h=HOJA38({now,...o});h.ctx.location.hash='#/cata';const d={...h.API.NEWDRAFT('','Toro'),rating:3};d.paso=h.API.PASOS.length-1;h.API.setCD(d);h.API.renderCata();return h};
 const pick=(h,f)=>h.els.cFotoF.onchange({target:{files:[f||png],value:'x'}});
 const gates=h=>{const g=[];h.ctx.A.resizeImage=()=>{const d=defer();g.push(d);return d.p};return g};
 /* 1. la foto guardada no se pierde si la nueva no se puede anotar en el teléfono */
 let h=open();await pick(h,png);await tick();const k1=h.API.getCD().foto;assert.ok(k1&&h.store.has(k1));
 const setItem=h.ctx.localStorage.setItem;h.ctx.localStorage.setItem=()=>{throw new Error('lleno')};
 await pick(h,png);await tick();
 assert.equal(h.API.getCD().foto,k1,'el borrador sigue con la foto de antes');assert.ok(h.store.has(k1),'y su archivo sigue en el teléfono');assert.equal(h.store.size,1,'la nueva no queda guardada');assert.match(h.els.cFotoH.textContent,/No hay espacio/);
 h.ctx.localStorage.setItem=setItem;
 /* quitar con el teléfono lleno: la foto se queda */
 h.ctx.localStorage.setItem=()=>{throw new Error('lleno')};h.els.cFotoX.onclick();await tick();assert.equal(h.API.getCD().foto,k1,'no se pudo anotar el cambio: la foto sigue');assert.ok(h.store.has(k1));h.ctx.localStorage.setItem=setItem;
 /* 2. una foto que termina cuando la persona ya está en el diario no cambia la página */
 h=open();let g=gates(h);const pend=pick(h);await tick();h.ctx.location.hash='#/mihoja/diario';h.ctx.view.innerHTML='<diario>';g[0].ok({blob:1});await pend;await tick();
 assert.equal(h.html(),'<diario>','la página del diario se queda como estaba');assert.equal(h.API.getCD().foto.startsWith('dfoto_'),true,'la foto queda en el borrador');assert.equal(JSON.parse(h.ls.get('lhb_mihoja_v1')).draft.foto,h.API.getCD().foto);
 /* 3. escoger A y luego B, terminando A al final: gana B */
 h=open();g=gates(h);const pa=pick(h),pb=pick(h);await tick();g[1].ok({blob:'B'});await pb;await tick();const kb=h.API.getCD().foto;assert.ok(kb);g[0].ok({blob:'A'});await pa;await tick();
 assert.equal(h.API.getCD().foto,kb,'la última escogida se queda');assert.equal(h.store.size,1,'la tardía se borra');assert.deepEqual([...h.store.keys()],[kb]);
 /* 3b. quitar mientras otra foto se está achicando: no vuelve */
 h=open();await pick(h);await tick();const k0=h.API.getCD().foto;g=gates(h);const pc=pick(h);await tick();h.els.cFotoX.onclick();await tick();assert.equal(h.API.getCD().foto,'');g[0].ok({blob:'C'});await pc;await tick();
 assert.equal(h.API.getCD().foto,'','la que llegó después de quitar no se restaura');assert.equal(h.store.size,0,'ni queda guardada');assert.equal(h.store.has(k0),false);
 /* 4. empezar una cata del catálogo desde el paso 0 borra la foto del borrador que se deja */
 h=open();await pick(h);await tick();const kd=h.API.getCD().foto;const dr=h.API.S().draft;dr.paso=0;h.API.S().draft=dr;h.API.write(h.API.S());
 h.API.vCata('c1');await tick();assert.equal(h.store.has(kd),false,'la foto abandonada se borra');assert.equal(h.API.getCD().foto,'');
});
test('LHB-38 (Codex ronda 2): ninguna foto se borra antes de que el cambio quede anotado en el teléfono: empezar otra cata, cambiar de borrador y borrar una entrada',async()=>{
 const now='2026-10-27T15:00:00.000Z';const png={type:'image/png',name:'a.png'};
 const open=()=>{const h=HOJA38({now});h.ctx.location.hash='#/cata';const d={...h.API.NEWDRAFT('','Toro'),rating:3};d.paso=h.API.PASOS.length-1;h.API.setCD(d);h.API.renderCata();return h};
 const lleno=h=>{const orig=h.ctx.localStorage.setItem;h.ctx.localStorage.setItem=()=>{throw new Error('lleno')};return ()=>{h.ctx.localStorage.setItem=orig}};
 const conFoto=async()=>{const h=open();await h.els.cFotoF.onchange({target:{files:[png],value:'x'}});await tick();const k=h.API.getCD().foto;assert.ok(k&&h.store.has(k));return {h,k}};
 /* empezar otra cata con el teléfono lleno: la foto del borrador que se deja sigue ahí (el teléfono todavía lo recuerda) */
 let {h,k}=await conFoto();let libre=lleno(h);h.API.startCata('','');await tick();assert.equal(h.store.has(k),true,'startCata: la foto se queda si el borrador nuevo no se pudo anotar');
 /* lo mismo desde una cata del catálogo con un borrador en el paso 0 */
 ({h,k}=await conFoto());const dr=h.API.S().draft;dr.paso=0;h.API.write(h.API.S());libre=lleno(h);h.API.vCata('c1');await tick();assert.equal(h.store.has(k),true,'vCata: la foto se queda si no se pudo anotar');
 libre();h.API.setCD(dr);h.API.persistDraft();h.API.vCata('c1');await tick();assert.equal(h.store.has(k),false,'vCata: con el teléfono libre se borra');
 /* borrar una entrada con el teléfono lleno: la entrada y su foto se quedan */
 const g=HOJA38({now,ls:{lhb_mihoja_v1:JSON.stringify({schema:1,humidor:[],ratings:{},diario:[E38({id:'a1',foto:'dfoto_a1'}),E38({id:'b2'})]})}});g.store.set('dfoto_a1',{blob:1});
 g.lists['[data-ddel]']=[{dataset:{ddel:'a1'},onclick:null}];g.API.vDiario();const btn=g.lists['[data-ddel]'][0];
 const lib2=lleno(g);const c0=g.API.S().cambios||0;await btn.onclick();await tick();
 assert.deepEqual(g.API.S().diario.map(e=>e.id),['a1','b2'],'la entrada sigue en pantalla y en memoria');assert.equal(g.store.has('dfoto_a1'),true,'y su foto');assert.equal(g.API.S().cambios||0,c0,'no cuenta como cambio');
 assert.equal(JSON.parse(g.ls.get('lhb_mihoja_v1')).diario.length,2,'el teléfono sigue con las dos');
 lib2();g.lists['[data-ddel]']=[{dataset:{ddel:'a1'},onclick:null}];g.API.vDiario();await g.lists['[data-ddel]'][0].onclick();await tick();assert.deepEqual(g.API.S().diario.map(e=>e.id),['b2']);assert.equal(g.store.has('dfoto_a1'),false,'con el teléfono libre se borra todo');
});
test('LHB-38 (Codex ronda 3): una foto que una entrada del diario usa no se borra; sin cuenta una foto tardía no reabre el formulario; lo que no se pudo borrar se borra en la próxima anotación',async()=>{
 const now='2026-10-27T15:00:00.000Z';const png={type:'image/png',name:'a.png'};
 const open=(o)=>{const h=HOJA38({now,...o});h.ctx.location.hash='#/cata';const d={...h.API.NEWDRAFT('','Toro'),rating:3,...(o&&o.draft||{})};d.paso=h.API.PASOS.length-1;h.API.setCD(d);h.API.renderCata();return h};
 const pick=(h,f)=>h.els.cFotoF.onchange({target:{files:[f||png],value:'x'}});
 const lleno=h=>{const orig=h.ctx.localStorage.setItem;h.ctx.localStorage.setItem=()=>{throw new Error('lleno')};return ()=>{h.ctx.localStorage.setItem=orig}};
 /* 1. el borrador y una entrada recuperada de un respaldo comparten la llave: abandonar el borrador no borra la foto de la entrada */
 let h=open({ls:{lhb_mihoja_v1:JSON.stringify({schema:1,humidor:[],ratings:{},diario:[E38({id:'r1',foto:'dfoto_k'})]})}});
 h.store.set('dfoto_k',{blob:1});h.API.getCD().foto='dfoto_k';h.API.persistDraft();
 h.API.startCata('','');await tick();assert.equal(h.store.has('dfoto_k'),true,'la foto que usa una entrada se queda');
 /* y una que nadie usa sí se borra */
 h=open();await pick(h,png);await tick();const k=h.API.getCD().foto;h.API.startCata('','');await tick();assert.equal(h.store.has(k),false);
 /* 2. sin cuenta (cerró sesión mientras se achicaba) la foto tardía no vuelve a pintar el formulario */
 h=open();const d=defer();h.ctx.A.resizeImage=async()=>{await d.p;return {blob:1}};const pend=pick(h);await tick();h.acctBox.v=null;h.ctx.view.innerHTML='<puerta de entrada>';d.ok();await pend;await tick();
 assert.equal(h.html(),'<puerta de entrada>','el formulario no reemplaza la puerta de la cuenta');
 /* 3. un cambio de borrador que no se pudo anotar deja la foto pendiente; la próxima anotación que funcione la borra */
 h=open();await pick(h,png);await tick();const k3=h.API.getCD().foto;let libre=lleno(h);h.API.startCata('','');await tick();assert.equal(h.store.has(k3),true,'con el teléfono lleno la foto se queda');
 libre();h.API.persistDraft();await tick();assert.equal(h.store.has(k3),false,'y se borra en cuanto una anotación funciona');
 /* pero si mientras tanto una entrada la usa, no */
 h=open({ls:{lhb_mihoja_v1:JSON.stringify({schema:1,humidor:[],ratings:{},diario:[]})}});await pick(h,png);await tick();const k4=h.API.getCD().foto;libre=lleno(h);h.API.startCata('','');libre();
 h.API.S().diario.push(E38({id:'z9',foto:k4}));h.API.persistDraft();await tick();assert.equal(h.store.has(k4),true,'una foto en uso no se borra');
});
test('LHB-38 (Codex ronda 4): el borrador guardado también cuenta como uso de la foto; lo pendiente se borra en cualquier anotación que funcione',async()=>{
 const now='2026-10-27T15:00:00.000Z';const png={type:'image/png',name:'a.png'};
 const lleno=h=>{const orig=h.ctx.localStorage.setItem;h.ctx.localStorage.setItem=()=>{throw new Error('lleno')};return ()=>{h.ctx.localStorage.setItem=orig}};
 /* 1. borrador guardado y entrada con la misma llave, sin ninguna cata abierta: borrar la entrada no borra la foto del borrador */
 const st={schema:1,humidor:[],ratings:{},diario:[E38({id:'r1',foto:'dfoto_k'})],draft:null};
 let h=HOJA38({now,ls:{lhb_mihoja_v1:JSON.stringify(st)}});
 st.draft={...h.API.NEWDRAFT('','Toro'),foto:'dfoto_k'};h.ls.set('lhb_mihoja_v1',JSON.stringify(st));
 h=HOJA38({now,ls:{lhb_mihoja_v1:JSON.stringify(st)}});h.store.set('dfoto_k',{blob:1});
 assert.equal(h.API.getCD(),null,'ninguna cata abierta');
 h.lists['[data-ddel]']=[{dataset:{ddel:'r1'},onclick:null}];h.API.vDiario();await h.lists['[data-ddel]'][0].onclick();await tick();
 assert.deepEqual(h.API.S().diario,[],'la entrada se borró');assert.equal(h.store.has('dfoto_k'),true,'pero el borrador guardado todavía usa su foto');
 /* 2. un cambio de borrador que no se pudo anotar; después cualquier anotación que funcione (por ejemplo hacer pública una entrada) borra la foto abandonada */
 const base={schema:1,humidor:[],ratings:{},diario:[E38({id:'p1'})]};
 h=HOJA38({now,ls:{lhb_mihoja_v1:JSON.stringify(base)}});h.ctx.location.hash='#/cata';const d={...h.API.NEWDRAFT('','Toro'),rating:3};d.paso=h.API.PASOS.length-1;h.API.setCD(d);h.API.renderCata();
 await h.els.cFotoF.onchange({target:{files:[png],value:'x'}});await tick();const k=h.API.getCD().foto;assert.ok(k);
 const libre=lleno(h);h.API.startCata('','');await tick();assert.equal(h.store.has(k),true,'con el teléfono lleno se queda');libre();
 h.lists['[data-dpub]']=[{dataset:{dpub:'p1'},checked:true,onchange:null}];h.API.vDiario();h.lists['[data-dpub]'][0].onchange();await tick();
 assert.equal(h.store.has(k),true,'el borrador guardado todavía la usa (el cambio de borrador se rechazó y se soltó), así que se queda');
 h.API.persistDraft();await tick();
 assert.equal(h.store.has(k),false,'en cuanto una anotación suelta el borrador que la usaba, la borra');
});
