test('LHB-28 (Codex ronda 1): juntar no se rompe con llaves como constructor o __proto__ y no contamina nada',()=>{
 const {LHB_MERGE:X}=SYNC28();const E=o=>({schema:1,creado:'2026-10-01',humidor:[],diario:[],pasaporte:{artesanos:{},cigarros:{},lugares:{}},favs:{artesanos:[],cigarros:[],lugares:[]},ratings:{},...o});
 const base=JSON.parse('{"ratings":{"constructor":3,"toString":2}}');
 let m;assert.doesNotThrow(()=>{m=X.merge(base,E({}),E({ratings:{constructor:3,toString:2}}))});assert.deepEqual(m.ratings,{},'lo que se quitó aquí y el otro no tocó se va, aunque se llame constructor');
 assert.doesNotThrow(()=>{m=X.merge(null,JSON.parse('{"ratings":{"__proto__":{"x":1},"a":2},"pasaporte":{"artesanos":{"__proto__":"2026-10-01","b":"2026-10-02"}}}'),E({}))});
 assert.deepEqual(m.ratings,{a:2});assert.deepEqual(m.pasaporte.artesanos,{b:'2026-10-02'});assert.equal(({}).x,undefined,'Object.prototype intacto');
 assert.equal(Object.getPrototypeOf(m.ratings),Object.prototype,'el resultado no cambia su propio prototipo');assert.equal(m.ratings.x,undefined,'lo de una llave __proto__ no se hereda');
 m=X.merge(null,E({ratings:{constructor:5}}),E({ratings:{}}));assert.equal(m.ratings.constructor,5,'una llave llamada constructor se guarda como cualquier otra');
});
test('LHB-28 (Codex ronda 1): el servidor mira el tamaño antes de leer el JSON, topa también favoritos, sellos y estrellas, rechaza If-Match mal cerrado y responde 503 si D1 falla al revisar el perfil',async()=>{
 const a=await API28();
 try{
  a.mk('user_a','ana_a');
  const big=n=>Array.from({length:n},(_,i)=>'f'+i);
  assert.equal((await a.put('user_a',{schema:1,doc:{favs:{cigarros:big(5001)}}},'0'))[0],413,'más de 5000 favoritos');
  assert.equal((await a.put('user_a',{schema:1,doc:{favs:{cigarros:'x'}}},'0'))[0],400,'favoritos que no son lista');
  assert.equal((await a.put('user_a',{schema:1,doc:{pasaporte:{lugares:Object.fromEntries(big(5001).map(k=>[k,'2026-10-01']))}}},'0'))[0],413,'más de 5000 sellos');
  assert.equal((await a.put('user_a',{schema:1,doc:{ratings:Object.fromEntries(big(5001).map(k=>[k,3]))}},'0'))[0],413,'más de 5000 estrellas');
  assert.equal((await a.put('user_a',{schema:1,doc:{favs:{cigarros:big(5000)}}},'0'))[0],200,'exactamente 5000 pasa');
  let parsed=0;const huge=a.rq(await a.tok('user_a'),'x'.repeat(1000001),{match:'1'});const orig=huge.json;huge.json=async()=>{parsed++;return orig()};
  let r=await a.M.onRequestPut({request:huge,env:a.env});assert.equal(r.status,413,'un cuerpo enorme se rechaza');assert.equal(parsed,0);
  r=await a.M.onRequestPut({request:a.rq(await a.tok('user_a'),{schema:1,doc:DOC28},{match:'1',len:'5000000'}),env:a.env});assert.equal(r.status,413,'el Content-Length enorme se rechaza sin leer el cuerpo');
  for(const m of ['"3','3"','"3 ','W/"3','""'])assert.deepEqual(await a.put('user_a',{schema:1,doc:DOC28},m),[428,{error:'if-match-required'}],'If-Match '+m);
  assert.equal((await a.put('user_a',{schema:1,doc:DOC28},'"1"'))[0],200,'comillas bien cerradas');
  const down={...a.env,DB:{prepare:sql=>sql.includes('FROM profiles')?{bind:()=>({first:async()=>{throw new Error('d1')}})}:a.env.DB.prepare(sql)}};
  assert.deepEqual(await a.get('user_a',down),[503,{error:'unavailable'}]);assert.deepEqual(await a.put('user_a',{schema:1,doc:DOC28},'2',undefined,down),[503,{error:'unavailable'}]);
 }finally{a.done()}
});
test('LHB-31 (Codex ronda 1): hoja.js lee Mi Hoja fresca para sincronizar, deja la copia en memoria por vieja cuando otra pestaña escribe, aparta lo de otra cuenta antes de leer y no cuenta como cambio lo que la app escribe sola',()=>{
 const h=readR('hoja.js').replace(/\r\n/g,'\n');
 assert.ok(h.includes("getDoc:()=>{ST=load();STRAW=localStorage.getItem(KEY);return ST}"),'la sincronización lee del almacenamiento y no de la copia en memoria');
 assert.ok(h.includes("window.addEventListener('storage',e=>{if(e.key===null||e.key===KEY)ST=null})"),'otra pestaña que escribe invalida la copia en memoria');
 assert.ok(h.includes("const S=()=>{try{if(SYNC&&!SYNC.isolate())return DEF();if(ST&&localStorage.getItem(KEY)===STRAW)return ST;ST=load();STRAW=localStorage.getItem(KEY);return ST}catch(e){ST=null;return DEF()}};"),/* LHB-101: dentro de un try */'S aparta lo de otra cuenta antes de leer, no muestra lo de la otra si no pudo y solo confía en la copia en memoria si el texto guardado no cambió');
 assert.ok(h.includes("if(SYNC&&!SYNC.isolate()){ST=null;toast('No se pudo separar lo de la otra cuenta. Libera espacio y vuelve a entrar.');return false}"),'write no escribe si no se pudo apartar lo de la otra cuenta y suelta la copia en memoria');
 assert.ok(h.includes("if(SYNC&&!quiet&&!SYNC.ensureOwner()){ST=null;toast('No hay espacio para guardar. Exporta un respaldo.');return false}")&&h.includes("STRAW=txt}catch(e){ST=null;toast('No hay espacio para guardar. Exporta un respaldo.');return false}"),'una escritura rechazada suelta la copia en memoria, que ya traía el cambio rechazado');
 assert.ok(read('sync.js').includes('if(inIso)return true;'),'aislar dentro de aislar se corta (write llama a isolate y isolate escribe por setDoc)');
 assert.ok(h.includes("s.migrado=(f||r)?'v5':'nuevo';write(s,true);return s}"),'la copia nueva o dañada que la app crea sola no cuenta como un cambio de la persona');
 assert.ok(h.includes("function write(s,quiet){")&&h.includes("if(SYNC&&!quiet)SYNC.changed(prev)")&&h.includes("if(SYNC&&!quiet)prev=localStorage.getItem(KEY)"),'write acepta quiet y pasa al motor lo que había antes de escribir');
 assert.ok(h.includes("lock:f=>navigator.locks&&navigator.locks.request?navigator.locks.request('lhb_mihoja_sync',f):f()"),'una sola pasada entre pestañas');
 assert.ok(h.includes("SYNC.isolate();SYNC.run('mi-hoja',{minAge:20e3})"),'abrir Mi Hoja aísla antes de pintar');
});
test('LHB-83: Leaflet no se pide al cargar la app; el mapa lo pide una vez y dibuja cuando llega',async()=>{const ix=read('index.html'),js=read('app.js'),sw=read('sw.js');
 assert.ok(!ix.includes('vendor-leaflet'),'la portada no pide vendor-leaflet.js ni vendor-leaflet.css');
 assert.ok(sw.includes("'vendor-leaflet.js'")&&sw.includes("'vendor-leaflet.css'"),'los dos siguen en el shell, para abrir sin red');assert.match(sw,/const VERSION='lhb-v166'/);
 const a=js.indexOf('let leafP=null'),b=js.indexOf('let rutaView=null;');assert.ok(a>0&&b>a,'el cargador vive antes de drawRuta');
 const mk=()=>{const app={tag:'link',href:'styles.css'};const els=[app];const doc={head:{insertBefore(e,ref){if(ref)els.splice(els.indexOf(ref),0,e);else els.push(e)}},createElement(t){const e={tag:t,remove(){els.splice(els.indexOf(e),1)}};return e},querySelector(q){return els.find(e=>e.tag==='link'&&q.includes('"'+e.href+'"'))||null}};
  const w={};const ctx={window:w,document:doc,Promise};require('vm').runInNewContext(js.slice(a,b)+';this.ready=()=>leafOK;',ctx);
  return {need:ctx.needLeaflet,ready:ctx.ready,w,app,els,scripts:()=>els.filter(e=>e.tag==='script'),links:()=>els.filter(e=>e.tag==='link'&&e!==app)}};
 let k=mk();const p1=k.need(),p2=k.need();assert.equal(p1,p2,'una sola carga aunque se pida dos veces');
 assert.ok(k.els.indexOf(k.links()[0])<k.els.indexOf(k.app),'el estilo de Leaflet va antes de styles.css, que lo ajusta');
 assert.equal(k.scripts().length,1);assert.equal(k.scripts()[0].src,'vendor-leaflet.js');assert.equal(k.links().length,1);assert.equal(k.links()[0].href,'vendor-leaflet.css');assert.equal(k.links()[0].rel,'stylesheet');
 k.w.L={};k.scripts()[0].onload();await null;assert.equal(k.ready(),false,'con el script pero sin el estilo, todavía no está listo');assert.equal(k.need(),p1,'quien pida ahora espera la misma carga (cambiar de modo no dibuja sin estilo)');
 k.links()[0].onerror();assert.equal(await p1,false,'si el estilo no llega, el mapa no se dibuja');assert.equal(k.ready(),false);assert.equal(k.links().length,0,'el estilo fallido se quita');
 const p3=k.need();assert.notEqual(p3,p1,'tras un fallo, la próxima entrada lo intenta otra vez');assert.equal(k.scripts().length,1,'el script que sí llegó no se pide otra vez');assert.equal(k.links().length,1,'el estilo se pide otra vez');
 k.links()[0].onload();assert.equal(await p3,true);assert.equal(k.ready(),true);assert.equal(await k.need(),true);assert.equal(k.scripts().length,1);assert.equal(k.links().length,1,'listo: no se pide nada más');
 k=mk();const q1=k.need();k.links()[0].onload();k.scripts()[0].onerror();assert.equal(await q1,false,'si el script no llega, el mapa no se dibuja');assert.equal(k.scripts().length,0,'el script fallido se quita');
 const q2=k.need();assert.equal(k.links().length,1,'el estilo que sí llegó no se repite');assert.equal(k.scripts().length,1);k.w.L={};k.scripts()[0].onload();assert.equal(await q2,true);assert.equal(k.ready(),true);
 for(const f of ['drawRuta','drawMap']){const s=js.indexOf('function '+f+'('),body=js.slice(s,js.indexOf('\nfunction ',s+1));assert.ok(body.includes('if(!leafOK){')&&body.includes('needLeaflet().then('),f+' espera a que Leaflet esté listo (script y estilo)');assert.ok(!body.includes('window.L'),f+' no mira window.L, que llega antes que el estilo')}
 assert.ok(js.includes("if(ok)drawRuta();else off(tt('map.failTown'))")&&js.includes("if(ok)drawMap(ps);else drawOffline(ps,tt('map.failPin'))"),'si Leaflet no llega, queda el mapa sin conexión y la lista');
});
test('LHB-88: el nombre accesible del enlace de la marca es su texto visible',()=>{const ix=read('index.html');const m=ix.match(/<a class="brand"[^>]*>([\s\S]*?)<\/a>/);assert.ok(m,'enlace de la marca');
 assert.ok(!/aria-label=/.test(m[0].match(/^<a[^>]*>/)[0]),'sin aria-label distinto del texto que se ve');assert.match(m[1],/<img [^>]*alt=""/,'el logo es decorativo');
 const txt=m[1].replace(/<\/span><span/g,'</span> <span').replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim();assert.equal(txt,'La Hoja Boricua Hecho en Borinquen');
 for(const f of ['build_lugares.py','build_cigarros.py','build_artesanos.py']){const t=fs.readFileSync(path.join(__dirname,'..','tools',f),'utf8');assert.ok(t.includes('<a class="brand" href="../"><img class="mark-l" src="../icons/icon.svg" alt="" width="30" height="30"><img class="mark-d" src="../icons/icon-dark.svg" alt="" width="30" height="30"><span class="brand-text"><span class="brand-name">La Hoja <em>Boricua</em></span><span class="brand-sub" lang="es">Hecho en Borinquen</span></span></a>'),f+': la marca de las páginas fijas (LHB-108: la firma, con el logo decorativo) se nombra por su texto')}
});
/* LHB-32: las páginas fijas en inglés viven en /en/<sección>/, cada una gemela de una en español */
const EN32={dirs:['lugares','artesanos','cigarros'],sec:{lugares:'Cigar lounges in Puerto Rico',artesanos:'Cigar artisans in Puerto Rico',cigarros:'Cigars made by Puerto Rican artisans'}};
const esc32=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#x27;');
const fx32=(r,k)=>{const e=r&&r[k+'_en'];return typeof e==='string'&&e.trim()?e:(r?r[k]:undefined)};
const html32=d=>fs.existsSync(path.join(S,d))?fs.readdirSync(path.join(S,d)).filter(f=>f.endsWith('.html')).sort():[];
test('LHB-32: cada página en inglés tiene su gemela en español y al revés; hreflang en ambas direcciones, x-default al español, canonical por idioma',()=>{
 const H='https://lahojaboricua.com';const alt=(h,l)=>[...h.matchAll(/<link rel="alternate" hreflang="([^"]+)" href="([^"]+)">/g)].filter(m=>m[1]===l).map(m=>m[2]);
 let pairs=0;
 for(const d of EN32.dirs){
  const es=html32(d),en=html32('en/'+d);assert.ok(es.length>1,d);
  assert.deepEqual(en,es,'las mismas páginas en /en/'+d+'/ que en /'+d+'/');
  for(const f of es){const id=f.replace(/\.html$/,''),tail=d+'/'+(id==='index'?'':id),uES=H+'/'+tail,uEN=H+'/en/'+tail;
   for(const [h,lang,canon,w] of [[read(d+'/'+f),'es-PR',uES,'es: '],[read('en/'+d+'/'+f),'en',uEN,'en: ']]){
    assert.ok(h.includes('<html lang="'+lang+'">'),w+'lang '+tail);
    assert.deepEqual([...h.matchAll(/<link rel="canonical" href="([^"]+)">/g)].map(m=>m[1]),[canon],w+'canonical de su idioma '+tail);
    assert.deepEqual(alt(h,'es'),[uES],w+'hreflang es '+tail);assert.deepEqual(alt(h,'en'),[uEN],w+'hreflang en '+tail);assert.deepEqual(alt(h,'x-default'),[uES],w+'x-default al español '+tail);
    assert.equal((h.match(/hreflang=/g)||[]).length,3,w+'solo esos tres '+tail);
   }
   pairs++;}
 }
 const n=JSON.parse(readD('places.json')).length+JSON.parse(readD('artesanos.json')).length+JSON.parse(readD('cigarros.json')).length+3;
 assert.equal(pairs,n,'cada registro y cada índice, en los dos idiomas');
 assert.deepEqual(fs.readdirSync(path.join(S,'en')).sort(),EN32.dirs.slice().sort(),'en /en/ solo las tres secciones');
});
test('LHB-32: sitemap bilingüe, cada página con sus alternativas',()=>{
 const H='https://lahojaboricua.com';const sm=read('sitemap.xml');
 assert.ok(sm.includes('<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">'),'espacio de nombres xhtml');
 const U=[...sm.matchAll(/<url>([\s\S]*?)<\/url>/g)].map(m=>({loc:(m[1].match(/<loc>([^<]+)<\/loc>/)||[])[1],alt:[...m[1].matchAll(/<xhtml:link rel="alternate" hreflang="([^"]+)" href="([^"]+)"\/>/g)].map(x=>x[1]+' '+x[2])}));
 const want=[H+'/'],pair=new Map();
 for(const d of EN32.dirs)for(const f of html32(d)){const id=f.replace(/\.html$/,''),tail=d+'/'+(id==='index'?'':id);want.push(H+'/'+tail,H+'/en/'+tail);pair.set(H+'/'+tail,tail);pair.set(H+'/en/'+tail,tail);}
 const solo=html32('guias').map(f=>H+'/guias/'+(f==='index.html'?'':f.replace(/\.html$/,'')));want.push(...solo);/* LHB-45: las guías son solo en español */
 assert.equal(U.length,want.length,'una entrada por página');
 assert.deepEqual(U.map(u=>u.loc).sort(),want.slice().sort(),'cada página en los dos idiomas, una vez, más el inicio');
 for(const u of U){if(u.loc===H+'/'||solo.includes(u.loc)){assert.deepEqual(u.alt,[],'el inicio y las guías no tienen gemela');continue}
  const t=pair.get(u.loc);assert.deepEqual(u.alt,['es '+H+'/'+t,'en '+H+'/en/'+t,'x-default '+H+'/'+t],'alternativas de '+u.loc);}
});
test('LHB-32: las páginas en inglés usan el inglés de los datos (o el español si falta), enlaces que existen y las reglas de las páginas en español',()=>{
 const H='https://lahojaboricua.com';const lds=h=>[...h.matchAll(/<script type="application\/ld\+json">(.*?)<\/script>/g)].map(m=>JSON.parse(m[1]));
 const data={lugares:JSON.parse(readD('places.json')),artesanos:JSON.parse(readD('artesanos.json')),cigarros:JSON.parse(readD('cigarros.json'))};
 const APP={lugares:()=>'../../#/lugares',artesanos:id=>id==='index'?'../../#/artesanos':'../../#/a/'+id,cigarros:id=>id==='index'?'../../#/catalogo':'../../#/c/'+id};
 const SPAN=['<dt>Tipo</dt>','<dt>Dirección</dt>','<dt>Horario</dt>','>Abrir en la app<','Cómo llegar (Google Maps)','>Sitio web<','Confirma horario y reglas','<h2>Más lugares en','<h2>Sus cigarros</h2>','Fortaleza: ','califícalo','Fuentes: ','Torcidos en Puerto Rico','<h2>Tiendas de cigarros</h2>','<h2>Lounges y lugares para fumar</h2>','cigarros en la guía','la guía de cigarros','Mapa y enlaces en','Enlaces y más en','de un artesano boricua','Cigarros artesanales','Artesanos de cigarros en Puerto Rico','Cigar lounges en Puerto Rico','Cigarros hechos por artesanos boricuas'];
 for(const s of SPAN)assert.ok(EN32.dirs.some(d=>html32(d).some(f=>read(d+'/'+f).includes(s))),'la lista de textos en español sale de las páginas en español: '+s);
 let n=0,shown=0;
 for(const d of EN32.dirs)for(const f of html32('en/'+d)){
  const h=read('en/'+d+'/'+f),id=f.replace(/\.html$/,''),w='en/'+d+'/'+f,canon=H+'/en/'+d+'/'+(id==='index'?'':id);n++;
  for(const s of SPAN)assert.ok(!h.includes(s),w+': sin texto de plantilla en español: '+s);
  for(const m of h.matchAll(/(?:href|src)="([^"]+)"/g)){const u=m[1];if(/^https?:/.test(u))continue;
   const p=path.posix.normalize(path.posix.join('en',d,u.split('#')[0]));const file=(p==='.'||p.endsWith('/'))?path.posix.join(p,'index.html'):p;
   assert.ok(!p.startsWith('..')&&fs.existsSync(path.join(S,file)),w+': el enlace '+u+' existe');
   assert.ok(!/\.html$/.test(file)||file.startsWith('en/')||file==='index.html',w+': no enlaza a una página fija en español: '+u);}
  assert.ok(h.includes('<a class="app" href="'+APP[d](id)+'">Open in the app</a>'),w+': abrir en la app');
  const all=lds(h),bc=all.filter(o=>o['@type']==='BreadcrumbList');assert.equal(bc.length,1,w);const it=bc[0].itemListElement;
  assert.equal(it[0].item,H+'/');assert.equal(it[1].item,H+'/en/'+d+'/');assert.equal(it[1].name,EN32.sec[d]);assert.equal(it[it.length-1].item,canon,w+': la última miga es la página');assert.equal(it.length,id==='index'?2:3,w);
  assert.ok(!/\d{3}[-. )]+\d{3}[-. ]\d{4}/.test(h)&&!/@[a-z0-9.-]+\.[a-z]{2,}|wa\.me|tel:/i.test(h),w+': sin teléfonos ni correos');
  if(id==='index')continue;
  const r=data[d].find(x=>x.id===id);assert.ok(r,w);const main=all[0];assert.equal(main.url,canon,w);assert.equal(main.name,r.nombre,w);
  const claim=/\b(made|rolled) in (PR|Puerto Rico)/i.test(h);/* como la regla en español: "hecho a mano en PR" (Handmade in PR) en las notas no cuenta */
  if(d==='lugares'){assert.ok(h.includes('<dd>'+esc32(fx32(r,'tipo'))+'</dd>'),w+': tipo');shown++;if(r.horario){assert.ok(h.includes('<dd>'+esc32(fx32(r,'horario'))+'</dd>'),w+': horario');shown++}assert.ok(!claim,w);}
  if(d==='artesanos'){const t=(fx32(r,'tipo')||'').trim();if(t){assert.ok(h.includes('<p class="tag">'+esc32(t)),w+': tipo');shown++}
   assert.equal(claim,!!(r.hecho_en_pr===true&&String(r.hecho_en_pr_fuente||'').trim()),w+': origen solo con fuente');
   for(const c of data.cigarros.filter(c=>c.artesano_id===r.id))assert.ok(h.includes('href="../cigarros/'+c.id+'.html"'),w+' '+c.id);}
  if(d==='cigarros'){const no=(fx32(r,'notas')||'').trim(),ca=(fx32(r,'capa')||'').trim();
   if(no){assert.ok(h.includes('<p>'+esc32(no)+'</p>'),w+': notas');shown++}
   if(ca){assert.ok(main.additionalProperty.some(p=>p.name==='Wrapper'&&p.value===ca),w+': capa');shown++}
   assert.equal(main['@type'],'Product');assert.ok(!('offers' in main)&&!/precio|price|\$\s?\d/i.test(JSON.stringify(main)),w+': sin precios en JSON-LD');assert.ok(!claim,w);}
 }
 assert.equal(n,data.lugares.length+data.artesanos.length+data.cigarros.length+3,'cada página en inglés contada');
 assert.ok(shown>=150,'campos traducidos a la vista (tipo y horario de lugares, tipo de artesanos, notas y capa de cigarros; 155 al 2026-10-28): '+shown);
});
/* LHB-32 (revisión adversarial): lo que queda de una página en inglés al quitarle los datos que no se traducen
   (nombres, direcciones, pueblos, vitolas, enlaces), el inglés de los datos y el español que se muestra solo
   cuando falta el inglés: texto visible, title, meta, alt y los textos del JSON-LD */
const TR32=['tipo','historia','nota','donde_comprar','capa','notas','horario'];
const ES32=/(^|[^\p{L}])(de|del|en|y|la|las|el|los|para|con|por|según|un|una|donde|dónde|cigarro|cigarros|artesano|artesanos|artesanales|lugar|lugares|tienda|tiendas|horario|dirección|fumar|guía|más|sus|abrir|ver|hecho|torcidos|confirma|antes|puedes|cómo|llegar|sitio|fuentes|fortaleza|capa|pueblo|tipo)(?=$|[^\p{L}])/iu;
const leftover32=()=>{const keep=new Set(['La Hoja Boricua','Hecho en Borinquen','Mi Hoja','Cigars Podcast']);/* LHB-108: el lema es parte de la marca */const add=v=>{if(typeof v!=='string'||!v.trim())return;const s=v.trim();keep.add(s);keep.add(s.replace(/\.$/,''));const m=s.match(/^(.+?)\s*\((.+)\)$/);if(m){keep.add(m[1].trim());keep.add(m[2].trim());keep.add(m[1].trim()+', '+m[2].trim())}};
 for(const f of ['places.json','artesanos.json','cigarros.json'])for(const r of JSON.parse(readD(f)))for(const [k,v] of Object.entries(r)){
  if(TR32.includes(k)){const e=r[k+'_en'];if(!(typeof e==='string'&&e.trim()))add(v);continue}
  if(k==='fortaleza')continue;/* Codex ronda 1: suave, media, fuerte se muestran como Mild, Medium, Full */
  for(const x of [].concat(v))add(x);}
 const K=[...keep].sort((a,b)=>b.length-a.length);const dec=s=>s.replace(/&quot;/g,'"').replace(/&#x27;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');
 return h=>{const strs=[];const walk=o=>{if(typeof o==='string')strs.push(o);else if(o&&typeof o==='object')for(const k of Object.keys(o))if(!['@context','@type','url','item','image','logo','sameAs'].includes(k))walk(o[k])};
  for(const m of h.matchAll(/<script type="application\/ld\+json">(.*?)<\/script>/g))walk(JSON.parse(m[1]));
  const body=h.replace(/<script[\s\S]*?<\/script>/g,' ');for(const m of body.matchAll(/(?:content|alt)="([^"]*)"/g))strs.push(dec(m[1]));
  strs.push(dec(body.replace(/<head>[\s\S]*?<title>/,'<title>').replace(/<[^>]+>/g,' ')));
  let t=strs.join(' \n ').replace(/\s+/g,' ');const low=t.toLowerCase();let out='',i=0;
  const cut=new Array(t.length).fill(false);for(const k of K){const kl=k.toLowerCase();let j=low.indexOf(kl);while(j>=0){for(let x=j;x<j+kl.length;x++)cut[x]=true;j=low.indexOf(kl,j+kl.length)}}
  for(;i<t.length;i++)out+=cut[i]?' ':t[i];return out.replace(/https?:\/\/\S+/g,' ')}};
test('LHB-32: en una página en inglés no queda español fuera de los datos que no se traducen (título, meta, alt, texto, JSON-LD)',()=>{
 const left=leftover32();let n=0,es=0;
 for(const d of EN32.dirs){for(const f of html32('en/'+d)){const rest=left(read('en/'+d+'/'+f));const m=rest.match(ES32);assert.ok(!m,'en/'+d+'/'+f+': queda español: "'+(m&&rest.slice(Math.max(0,m.index-40),m.index+40).replace(/\s+/g,' '))+'"');n++}
  for(const f of html32(d))if(ES32.test(left(read(d+'/'+f))))es++;}
 assert.equal(n,html32('lugares').length+html32('artesanos').length+html32('cigarros').length,'cada página en inglés revisada');
 assert.equal(es,n,'la misma revisión sí encuentra el español en cada página en español');
 const P=JSON.parse(readD('places.json')),A=JSON.parse(readD('artesanos.json')),C=JSON.parse(readD('cigarros.json'));const desc=h=>h.match(/<meta name="description" content="([^"]*)">/)[1];
 for(const p of P)assert.ok(desc(read('en/lugares/'+p.id+'.html')).startsWith(esc32(p.nombre+': '+fx32(p,'tipo').toLowerCase()+' in ')),'meta del lugar con su tipo en inglés '+p.id);
 for(const a of A){const t=(fx32(a,'tipo')||'').trim();if(t)assert.ok(desc(read('en/artesanos/'+a.id+'.html')).startsWith(esc32(a.nombre+': '+t.toLowerCase()+((a.pueblo||'').trim()?' in ':', Puerto Rico'))),'meta del artesano con su tipo en inglés '+a.id)}
 /* donde el inglés de un campo es otro, su español no aparece como palabras enteras en la página en inglés del registro */
 const dec=s=>s.replace(/&quot;/g,'"').replace(/&#x27;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');const reEsc=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');let pairs=0;
 for(const [d,rs] of [['lugares',P],['artesanos',A],['cigarros',C]])for(const r of rs){const page=left(read('en/'+d+'/'+r.id+'.html')).replace(/\s+/g,' ').toLowerCase();/* sin nombres ni datos que no se traducen: "Tabacalera" es un tipo y también parte de un nombre */
  for(const k of TR32){const es=r[k],en=r[k+'_en'];if(!(typeof es==='string'&&es.trim()&&typeof en==='string'&&en.trim()))continue;const s=es.trim().replace(/\s+/g,' ').toLowerCase();if(s===en.trim().replace(/\s+/g,' ').toLowerCase())continue;pairs++;
   assert.ok(!new RegExp('(^|[^\\p{L}])'+reEsc(s)+'(?=$|[^\\p{L}])','u').test(page),'en/'+d+'/'+r.id+': el español de '+k+' aparece: '+es.slice(0,60))}}
 assert.ok(pairs>=150,'campos con un inglés distinto revisados: '+pairs);
 for(const c of C){const ca=(fx32(c,'capa')||'').trim(),h=read('en/cigarros/'+c.id+'.html');if(ca)assert.ok(h.includes('<li>Wrapper: <span>'+esc32(ca)+'</span></li>'),'la capa visible en inglés '+c.id);
  const st={suave:'Mild',media:'Medium',fuerte:'Full'}[c.fortaleza];if(c.fortaleza){assert.ok(st,'fortaleza conocida '+c.id);assert.ok(h.includes('<li>Strength: <span>'+st+'</span></li>'),'la fortaleza visible en inglés '+c.id);
   const main=JSON.parse(h.match(/<script type="application\/ld\+json">(.*?)<\/script>/)[1]);assert.ok(main.additionalProperty.some(p=>p.name==='Strength'&&p.value===st),'la fortaleza del JSON-LD en inglés '+c.id)}}
});
test('LHB-32: el service worker no guarda una página de /en/ como el shell ni la precarga',()=>{const sw=read('sw.js');
 const nav=sw.replace(/\/\*[\s\S]*?\*\//g,'').split(/\r?\n/).filter(l=>l.includes("req.mode==='navigate'")).map(l=>l.replace(/\/\/.*$/,''));
 assert.equal(nav.length,1,'una regla de navegación');assert.ok(/if\(r\.ok&&!r\.redirected&&[^{]*!url\.pathname\.startsWith\('\/en\/'\)[^{]*\)caches\.open\(VERSION\)\.then\(c=>c\.put\('\.\/',cp\)\)/.test(nav[0]),'/en/ fuera del shell, en la condición que guarda el shell');
 assert.ok(!/'en\//.test(sw),'/en/ fuera del precache');
});
/* LHB-45: guías de preguntas y respuestas en /guias/, en español, hechas solo con los datos */
const G45=()=>{const P=JSON.parse(readD('places.json')),A=JSON.parse(readD('artesanos.json')),C=JSON.parse(readD('cigarros.json'));
 const py=require('child_process').spawnSync('python',['-c','import sys,json;sys.path.insert(0,"tools");from build_lugares import municipio,P;from build_guias import slug;print(json.dumps({p["id"]:[municipio(p),slug(municipio(p))] for p in P}))'],{cwd:path.join(__dirname,'..'),encoding:'utf8'});
 assert.equal(py.status,0,py.stderr);return {P,A,C,mun:JSON.parse(py.stdout),files:html32('guias')}};
const dec45=s=>s.replace(/&quot;/g,'"').replace(/&#x27;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');
test('LHB-45: cada lugar, artesano y cigarro nombrado en una guía existe en los datos, con su nombre; los enlaces existen',()=>{
 const {P,A,C,files}=G45();const by={lugares:new Map(P.map(r=>[r.id,r])),artesanos:new Map(A.map(r=>[r.id,r])),cigarros:new Map(C.map(r=>[r.id,r]))};
 assert.ok(files.includes('index.html')&&files.length>=4,'guías generadas: '+files.length);let links=0;
 for(const f of files){const h=read('guias/'+f),w='guias/'+f;
  for(const m of h.matchAll(/<a href="\.\.\/(lugares|artesanos|cigarros)\/([^"]*)">([^<]*)<\/a>/g)){if(!m[2])continue;const id=m[2].replace(/\.html$/,'');const r=by[m[1]].get(id);
   assert.ok(m[2].endsWith('.html')&&r,w+': '+m[1]+'/'+m[2]+' existe en los datos');assert.equal(m[3],esc32(r.nombre),w+': el nombre de '+m[1]+'/'+id);links++}
  for(const m of h.matchAll(/<a [^>]*>([^<]*)<\/a>/g))if(/^\s*$/.test(m[1]))assert.fail(w+': enlace sin texto');
  for(const m of h.matchAll(/(?:href|src)="([^"]+)"/g)){const u=m[1];if(/^https?:/.test(u))continue;const p=path.posix.normalize(path.posix.join('guias',u.split('#')[0]));
   const file=(p==='.'||p.endsWith('/'))?path.posix.join(p,'index.html'):p;assert.ok(!p.startsWith('..')&&fs.existsSync(path.join(S,file)),w+': el enlace '+u+' existe')}
  assert.ok(!/\d{3}[-. )]+\d{3}[-. ]\d{4}/.test(h)&&!/@[a-z0-9.-]+\.[a-z]{2,}|wa\.me|tel:/i.test(h),w+': sin teléfonos ni correos');
 }
 assert.ok(links>=P.length+A.length,'enlaces a los datos: '+links);
});
test('LHB-45: cada guía responde su pregunta en el primer párrafo y lo marca como FAQPage; migas, canonical, sitemap y llms.txt',()=>{
 const H='https://lahojaboricua.com';const {files}=G45();const sm=read('sitemap.xml'),tx=read('llms.txt');const ix=read('guias/index.html');
 for(const f of files){const h=read('guias/'+f),id=f.replace(/\.html$/,''),url=H+'/guias/'+(id==='index'?'':id),w='guias/'+f;
  assert.ok(h.includes('<html lang="es-PR">')&&!/hreflang=/.test(h),w+': en español, sin gemela');
  assert.deepEqual([...h.matchAll(/<link rel="canonical" href="([^"]+)">/g)].map(m=>m[1]),[url],w+': canonical');
  assert.ok(sm.includes('<url><loc>'+url+'</loc></url>'),w+': en el sitemap');assert.ok(tx.includes('('+url+')'),w+': en llms.txt');
  const lds=[...h.matchAll(/<script type="application\/ld\+json">(.*?)<\/script>/g)].map(m=>JSON.parse(m[1]));const bc=lds.filter(o=>o['@type']==='BreadcrumbList');assert.equal(bc.length,1,w);
  const it=bc[0].itemListElement;assert.equal(it[0].item,H+'/');assert.equal(it[1].item,H+'/guias/');assert.equal(it[1].name,'Guías de cigarros en Puerto Rico');assert.equal(it[it.length-1].item,url,w);assert.equal(it.length,id==='index'?2:3,w);
  if(id==='index')continue;
  assert.ok(ix.includes('<a href="'+id+'.html">'),w+': el índice la enlaza');
  const m=h.match(/<main>\s*<h1>([^<]+)<\/h1>\s*<p class="answer">([\s\S]*?)<\/p>/);assert.ok(m,w+': la pregunta y enseguida su respuesta');
  const q=dec45(m[1]),ans=dec45(m[2].replace(/<[^>]+>/g,''));assert.ok(q.startsWith('¿')&&q.endsWith('?'),w+': el título es una pregunta');assert.ok(ans.length>=60,w+': respuesta de verdad');
  const faq=lds.filter(o=>o['@type']==='FAQPage');assert.equal(faq.length,1,w+': un FAQPage');const qs=faq[0].mainEntity;
  assert.equal(qs.length,1);assert.equal(qs[0]['@type'],'Question');assert.equal(qs[0].name,q,w+': la pregunta del FAQPage es el título');assert.equal(qs[0].acceptedAnswer['@type'],'Answer');assert.equal(qs[0].acceptedAnswer.text,ans,w+': la respuesta del FAQPage es el primer párrafo');
  assert.equal(dec45(h.match(/<title>([^<]+)<\/title>/)[1]),q+' | La Hoja Boricua',w);
  /* como en las páginas de artesano (v40): el origen solo junto a un artesano que tiene fuente (p. ej. su tipo, "torcido en PR") */
  const fuente=new Set(JSON.parse(readD('artesanos.json')).filter(a=>a.hecho_en_pr===true&&String(a.hecho_en_pr_fuente||'').trim()).map(a=>a.id));const CL=/(hecho|torcido)s? en (PR|Puerto Rico)/i;
  if(id!=='que-es-un-cigarro-hecho-en-puerto-rico')for(const seg of h.split('<li>'))if(CL.test(seg)){const a=seg.match(/^<a href="\.\.\/artesanos\/([^"]+)\.html">[^<]*<\/a>[^<]*(<span>[^<]*<\/span>)?<\/li>/);assert.ok(a&&fuente.has(a[1])&&CL.test(a[2]||''),w+': reclamo de origen sin fuente: '+seg.slice(0,80))}
 }
});
test('LHB-45: una guía de dónde fumar por pueblo con lugares, con cada lugar de ese pueblo y solo esos',()=>{
 const {P,A,C,mun,files}=G45();const want=new Map();for(const p of P){const [m,s]=mun[p.id];if(!want.has(s))want.set(s,{m,ps:[]});want.get(s).ps.push(p)}
 const got=files.filter(f=>f.startsWith('donde-fumar-cigarros-en-')).map(f=>f.slice(24,-5)).sort();assert.deepEqual(got,[...want.keys()].sort(),'una guía por pueblo con lugares');
 for(const [s,{m,ps}] of want){const h=read('guias/donde-fumar-cigarros-en-'+s+'.html'),w='guía '+s;assert.ok(h.includes('<h1>¿Dónde fumar cigarros en '+esc32(m)+'?</h1>'),w);
  const ids=[...h.matchAll(/<li><a href="\.\.\/lugares\/([^"]+)\.html">/g)].map(x=>x[1]);assert.deepEqual(ids.slice().sort(),ps.map(p=>p.id).sort(),w+': la lista es el pueblo');
  const ans=h.match(/<p class="answer">([\s\S]*?)<\/p>/)[1];const inAns=[...ans.matchAll(/href="\.\.\/lugares\/([^"]+)\.html"/g)].map(x=>x[1]).sort();assert.deepEqual(inAns,ps.map(p=>p.id).sort(),w+': la respuesta nombra cada lugar');
  const L=ps.filter(p=>p.categoria==='lounge'),V=ps.filter(p=>p.categoria!=='lounge');
  for(const [lst,hd] of [[L,'Lounges y lugares para fumar en '],[V,'Tiendas de cigarros en ']]){const i=h.indexOf('<h2>'+hd+esc32(m)+'</h2>');assert.equal(i>=0,lst.length>0,w+': '+hd);
   if(lst.length){const ul=h.slice(i,h.indexOf('</ul>',i));assert.deepEqual([...ul.matchAll(/href="\.\.\/lugares\/([^"]+)\.html"/g)].map(x=>x[1]).sort(),lst.map(p=>p.id).sort(),w+': '+hd)}}
  if(L.length)assert.ok(ans.includes(String(L.length)),w+': cuántos lugares para fumar');else assert.ok(dec45(ans).startsWith('La guía no tiene lounges ni lugares para fumar en '+m+'.'),w+': lo dice si no hay dónde fumar');
 }
 const hq=read('guias/que-es-un-cigarro-hecho-en-puerto-rico.html');const src=A.filter(a=>a.hecho_en_pr===true&&String(a.hecho_en_pr_fuente||'').trim());
 assert.deepEqual([...hq.matchAll(/<h2><a href="\.\.\/artesanos\/([^"]+)\.html">/g)].map(x=>x[1]).sort(),src.map(a=>a.id).sort(),'hecho en PR: solo los artesanos con fuente');
 for(const a of src){for(const c of C.filter(c=>c.artesano_id===a.id))assert.ok(hq.includes('href="../cigarros/'+c.id+'.html"'),'sus cigarros '+c.id);const f=a.hecho_en_pr_fuente.trim();if(f.startsWith('http'))assert.ok(hq.includes('href="'+esc32(f)+'"'),'su fuente '+a.id)}
 const hp=read('guias/artesanos-de-cigarros-por-pueblo.html');const ids=[...hp.matchAll(/<li><a href="\.\.\/artesanos\/([^"]+)\.html">/g)].map(x=>x[1]);
 assert.deepEqual(ids.slice().sort(),A.map(a=>a.id).sort(),'artesanos por pueblo: cada artesano una vez');
 /* Codex ronda 2: cada artesano bajo su pueblo, y las cuentas de la respuesta salen de los datos */
 const base=a=>{const pu=String(a.pueblo||'').trim();if(!pu)return null;const m=pu.match(/^(.+?)\s*\(/);return m?m[1].trim():pu};const grp=new Map();for(const a of A){const k=base(a);if(!grp.has(k))grp.set(k,[]);grp.get(k).push(a.id)}
 const secs=[...hp.matchAll(/<h2>([^<]+)<\/h2>\s*<ul>([\s\S]*?)<\/ul>/g)].map(m=>[dec45(m[1]),[...m[2].matchAll(/href="\.\.\/artesanos\/([^"]+)\.html"/g)].map(x=>x[1]).sort()]);
 assert.deepEqual(secs.map(s=>s[0]).sort(),[...grp.keys()].map(k=>k===null?'Sin pueblo en la guía':k).sort(),'una sección por pueblo o zona');
 for(const [k,v] of grp)assert.deepEqual(secs.find(s=>s[0]===(k===null?'Sin pueblo en la guía':k))[1],v.slice().sort(),'los artesanos de '+k);
 const named=[...grp.keys()].filter(k=>k!==null),con=named.reduce((n,k)=>n+grp.get(k).length,0),ap=dec45(hp.match(/<p class="answer">([\s\S]*?)<\/p>/)[1]);
 assert.ok(ap.startsWith('La Hoja Boricua tiene '+A.length+' artesanos de cigarros. '+con+' tienen pueblo o zona en la guía, en '+named.length+' pueblos y zonas: '),'las cuentas de la respuesta: '+ap.slice(0,140));
 for(const k of named)assert.ok(ap.includes(k+' ('+grp.get(k).length+')'),'la respuesta cuenta '+k);
 if(grp.has(null))assert.ok(ap.includes(' De '+grp.get(null).length+' artesano'),'los que no tienen pueblo');
});
