 for(const k of keys){assert.ok(typeof T.es[k]==='string'&&T.es[k].length,'es '+k);assert.ok(typeof T.en[k]==='string'&&T.en[k].length,'en '+k);assert.notEqual(T.en[k],T.es[k],'en traducido '+k)}
