 doc={root,body,activeElement:body,createElement:t=>new N(t),querySelector:s=>root.querySelector(s),querySelectorAll:s=>root.querySelectorAll(s),addEventListener:(t,f)=>{(ls[t]=ls[t]||[]).push(f)}};
