  if(m[1]){if(!st.length&&++roots>1)return false;const ns=[...m[2].matchAll(/([a-zA-Z_][\w:.-]*)=/g)].map(x=>x[1]);if(new Set(ns).size!==ns.length)return false;if(!m[3])st.push(m[1])}
